files.examples/01_gin_jsonb_arrays.sql:
-- LEARN(sql.indexes.gin-brgin): GIN indexes the parts of a value: keys, elements, words.
CREATE TABLE products (
  id    int PRIMARY KEY,
  attrs jsonb NOT NULL,
  tags  text[] NOT NULL
);
INSERT INTO products
SELECT g,
       jsonb_build_object(
         'brand', 'marka-' || g % 200,
         'color', (ARRAY['kırmızı', 'mavi', 'yeşil', 'siyah'])[g % 4 + 1],
         'stock', g % 50),
       ARRAY[(ARRAY['indirim', 'yeni', 'outlet', 'premium'])[g % 4 + 1], 'kategori-' || g % 100]
FROM generate_series(1, 20000) AS g;
ANALYZE products;

-- jsonb_ops (the default): an entry for every key and every value.
CREATE INDEX products_attrs ON products USING gin (attrs);
EXPLAIN (COSTS OFF)
SELECT id FROM products WHERE attrs @> '{"brand": "marka-7", "color": "siyah"}';

-- Key existence is a GIN operator too...
EXPLAIN (COSTS OFF)
SELECT id FROM products WHERE attrs ? 'discount';

-- ...but ->> yields text, and = on text is not a GIN operator.
EXPLAIN (COSTS OFF)
SELECT id FROM products WHERE attrs ->> 'brand' = 'marka-7';

-- jsonb_path_ops: containment only, in a smaller index.
CREATE INDEX products_attrs_path ON products USING gin (attrs jsonb_path_ops);
SELECT pg_relation_size('products_attrs') / 8192 AS jsonb_ops_pages,
       pg_relation_size('products_attrs_path') / 8192 AS jsonb_path_ops_pages;

-- Arrays: contains (@>) and overlaps (&&) use the index; = ANY doesn't.
CREATE INDEX products_tags ON products USING gin (tags);
EXPLAIN (COSTS OFF)
SELECT id FROM products WHERE tags @> ARRAY['kategori-7', 'yeni'];
EXPLAIN (COSTS OFF)
SELECT id FROM products WHERE 'kategori-7' = ANY (tags);

files.examples/02_gin_text.sql:
-- Full-text search: the turkish configuration reduces words to stems.
SELECT to_tsvector('turkish', 'Kitapçılar yeni kitapları tanıttı') AS document,
       to_tsquery('turkish', 'kitaplar') AS query;

CREATE TABLE articles (id int PRIMARY KEY, title text NOT NULL, body text NOT NULL);
INSERT INTO articles
SELECT g,
       (ARRAY['İstanbul', 'Ankara', 'İzmir', 'Bursa', 'Antalya'])[g % 5 + 1] || ' haberleri ' || g,
       (ARRAY['Kitapçılar yeni kitapları tanıttı', 'Belediye otobüs saatlerini değiştirdi',
              'Sahilde bisiklet yolu açıldı', 'Müzede yeni sergi başladı',
              'Pazarda sebze fiyatları düştü'])[g % 5 + 1]
         || ' ' || (ARRAY['bugün', 'dün', 'bu hafta', 'geçen ay'])[g % 4 + 1]
FROM generate_series(1, 20000) AS g;

-- A GIN index on the tsvector: for every stem, the rows that contain it.
CREATE INDEX articles_body_fts ON articles USING gin (to_tsvector('turkish', body));
ANALYZE articles;
EXPLAIN (COSTS OFF)
SELECT count(*) FROM articles
WHERE to_tsvector('turkish', body) @@ to_tsquery('turkish', 'kitap & dün');
SELECT count(*) FROM articles
WHERE to_tsvector('turkish', body) @@ to_tsquery('turkish', 'kitap & dün');

-- Without the configuration argument it's a different expression.
EXPLAIN (COSTS OFF)
SELECT count(*) FROM articles
WHERE to_tsvector(body) @@ to_tsquery('turkish', 'kitap & dün');

-- Substrings (LIKE '%...%') need pg_trgm: three-character pieces of each word.
CREATE EXTENSION pg_trgm;
SELECT show_trgm('haber');
EXPLAIN (COSTS OFF)
SELECT count(*) FROM articles WHERE title ILIKE '%zmir haberleri 12%';
CREATE INDEX articles_title_trgm ON articles USING gin (title gin_trgm_ops);
EXPLAIN (COSTS OFF)
SELECT count(*) FROM articles WHERE title ILIKE '%zmir haberleri 12%';
SELECT count(*) FROM articles WHERE title ILIKE '%zmir haberleri 12%';

-- Turkish letters: what counts as a letter comes from the database's LC_CTYPE.
SELECT datctype = 'C' AS ctype_is_c,
       show_trgm('ığdır') AS igdir,
       similarity('ığdır', 'dür') AS vs_dur,
       similarity('IĞDIR', 'ığdır') AS upper_case
FROM pg_database WHERE datname = current_database();

files.examples/03_brin_skip_scan.sql:
-- Plans print timestamptz constants in the session's time zone: pin it.
SET LOCAL TimeZone = 'Europe/Istanbul';
CREATE TABLE readings (
  sensor_id int NOT NULL,
  at        timestamptz NOT NULL,
  value     int NOT NULL
);
-- Append-only: 4 sensors, one reading each per minute, oldest rows first.
INSERT INTO readings
SELECT g % 4 + 1, timestamptz '2026-01-01 00:00+03' + (g / 4) * interval '1 minute',
       (g * 7919) % 1000
FROM generate_series(0, 19999) AS g;
ANALYZE readings;

-- How closely each column follows the physical row order (1 = exactly).
SELECT attname, round(correlation::numeric, 2) AS correlation
FROM pg_stats
WHERE schemaname = current_schema() AND tablename = 'readings'
ORDER BY attname;

-- BRIN: one min/max summary per range of 8 table pages.
CREATE INDEX readings_at_brin ON readings USING brin (at) WITH (pages_per_range = 8);
CREATE INDEX readings_at_btree ON readings (at);
SELECT pg_relation_size('readings') / 8192 AS table_pages,
       pg_relation_size('readings_at_brin') / 8192 AS brin_pages,
       pg_relation_size('readings_at_btree') / 8192 AS btree_pages;
DROP INDEX readings_at_btree;

EXPLAIN (COSTS OFF)
SELECT count(*) FROM readings WHERE at >= '2026-01-02 10:00' AND at < '2026-01-02 11:00';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT count(*) FROM readings WHERE at >= '2026-01-02 10:00' AND at < '2026-01-02 11:00';

-- Skip scan (PG 18): the index leads with sensor_id, the query never names it.
DROP INDEX readings_at_brin;
CREATE INDEX readings_sensor_at ON readings (sensor_id, at);
SELECT pg_relation_size('readings_sensor_at') / 8192 AS index_pages;
EXPLAIN (COSTS OFF)
SELECT count(*) FROM readings WHERE at >= '2026-01-02 10:00' AND at < '2026-01-02 11:00';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT count(*) FROM readings WHERE at >= '2026-01-02 10:00' AND at < '2026-01-02 11:00';
